var storageKey='ybs-books-v2-review-1',setupStep=0,activeCustomer=null,assetPending=0;
var clone=function(x){return JSON.parse(JSON.stringify(x))};
var emptyOrg={name:'',display:'',address:'',city:'',region:'Andhra Pradesh',pin:'',country:'India',email:'',phone:'',website:'',taxStatus:'unregistered',gstin:'',pan:'',fy:'2026–27',currency:'INR',addressFormat:'stacked',logo:'',bankName:'',accountName:'',accountNo:'',ifsc:'',branch:'',upi:'',qr:'',signature:'',note:'Thank you for your business.',terms:'',prefix:'INV-2026-',nextNo:1,defaultDays:15,template:'classic',showBank:true,showQr:true,showSignature:true};
state.org=null;state.orgDraft=clone(emptyOrg);state.customers=[];state.documents=[];state.customerDraft={};state.itemDraft={};state.catalogue=[{id:'item-web',name:'Website design package',kind:'services',hsn:'998314',unit:'service',rate:50000,tax:18},{id:'item-goods',name:'Sample office equipment',kind:'goods',hsn:'8471',unit:'nos',rate:25000,tax:18}];
