var originalState=clone(state),originalCalc=calc,originalPreview=preview,originalInvoicePage=invoicePage,originalContactsPage=contactsPage,originalItemsPage=itemsPage,originalSettingsPage=settingsPage,originalDashboard=dashboard,originalAction=action,originalRender=render,originalUpdate=updateTotals,originalOrderPage=orderPage,originalBillPage=billPage;
try{var saved=JSON.parse(localStorage.getItem(storageKey)||'null');if(saved&&saved.version===1&&saved.data&&Array.isArray(saved.data.documents)&&Array.isArray(saved.data.customers)){Object.assign(state,saved.data);state.route='dashboard';state.customerDraft={};state.itemDraft={}}}catch(ignore){}
function persist(){try{localStorage.setItem(storageKey,JSON.stringify({version:1,data:state}));return true}catch(err){message('Browser storage is full or unavailable. Export your review data before closing.');return false}}
function download(name,content,type){var blob=new Blob([content],{type:type||'text/plain;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(function(){URL.revokeObjectURL(url)},10000)}
function orgReady(){return state.org&&state.org.name&&state.org.address&&state.org.city&&state.org.pin}
function fail(s){var x=document.getElementById('form-error');if(x){x.textContent=s;x.setAttribute('role','alert');x.scrollIntoView({block:'center',behavior:'smooth'})}message(s);return false}
function errorBox(){return '<p id="form-error" class="form-error" aria-live="polite"></p>'}
function selectOptions(data){return data.map(function(x){return [x.id,x.name]})}
function requiredLabel(html){return html.replace(/<label for=/g,'<label for=')}
function orgAddress(o){var lines=[o.address,o.city+(o.pin?' – '+o.pin:''),o.region,o.country].filter(Boolean);return lines.join(o.addressFormat==='compact'?', ':'\n')}
function uploadField(label,key){var o=state.orgDraft;return '<div class="field"><label for="upload-'+key+'">'+esc(label)+' · PNG/JPEG, max 1 MB</label><input id="upload-'+key+'" type="file" accept="image/png,image/jpeg" data-asset="'+key+'">'+(o[key]?'<img class="asset-sample" src="'+o[key]+'" alt="Uploaded '+esc(label)+'">'+b('Remove '+label,'remove-'+key,'secondary small'):'<p class="miniinfo">Optional. No image is uploaded to a server.</p>')+'</div>'}
function checkOrg(step){var o=state.orgDraft;if(step===0){if(!o.name.trim()||!o.address.trim()||!o.city.trim()||!o.pin.trim()||!o.region.trim())return fail('Enter the legal name, street address, city, state and PIN code.');if(!/^\d{6}$/.test(o.pin))return fail('Use a six digit Indian PIN code.');if(o.email&&!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(o.email))return fail('Enter a valid email address.')}if(step===1){if(o.taxStatus==='registered'&&!/^\d{2}[A-Z]{5}\d{4}[A-Z][1-9A-Z]Z[0-9A-Z]$/.test(o.gstin))return fail('Enter a 15 character GSTIN in the expected format. This checks format only.');if(!o.prefix.trim()||!Number.isInteger(Number(o.nextNo))||Number(o.nextNo)<1)return fail('Enter an invoice prefix and a positive whole starting number.');if((o.prefix+String(o.nextNo).padStart(3,'0')).length>16)return fail('Keep the invoice number, including prefix, within 16 characters.');if(!Number.isInteger(Number(o.defaultDays))||Number(o.defaultDays)<0)return fail('Payment terms must be a whole number of days, zero or more.')}if(step===2){var hasBank=o.bankName||o.accountName||o.accountNo||o.ifsc;if(hasBank&&(!o.bankName||!o.accountName||!o.accountNo||!o.ifsc))return fail('Complete bank, account holder, account number and IFSC, or leave all four empty.');if(o.ifsc&&!/^[A-Z]{4}0[A-Z0-9]{6}$/.test(o.ifsc))return fail('Enter an IFSC in the expected 11 character format.');if(o.upi&&!/^[^\s@]+@[^\s@]+$/.test(o.upi))return fail('Enter a UPI ID in name@provider format.')}return true}
function setupPage(){var names=['Business identity','Tax & numbering','Bank & payment QR','Invoice appearance','Review & finish'],o=state.orgDraft;
 var h=head('ORGANIZATION SETUP',state.org?'Organization & invoice settings':'Make every invoice yours','Set this up once. Your business details become the default on new invoices.',b('Use sample organization','sample-org','secondary'));
 h+='<div class="setup-progress">'+names.map(function(n,i){return '<button type="button" data-step="'+i+'" class="'+(i===setupStep?'active':'')+'" '+(i>setupStep?'disabled':'')+'>'+String(i+1).padStart(2,'0')+' · '+n+'</button>'}).join('')+'</div><div class="setup-layout"><section class="panel panelpad"><p class="eyebrow">STEP '+(setupStep+1)+' OF 5</p><h2 class="section-title">'+names[setupStep]+'</h2><p class="muted">'+['Legal identity and address. Fields marked * are required.','India edition · INR. Tax identifiers are checked for format only.','Optional details shown on invoices when enabled. An uploaded QR is a payment image, not an IRP signed QR.','Choose defaults for new documents. Previously issued copies keep their original appearance.','Check your details, then finish setup to create invoices.'][setupStep]+'</p>';
 if(setupStep===0)h+='<div class="formgrid">'+field('Legal company / organization name *','orgDraft','name')+field('Trading / display name','orgDraft','display')+field('Street address *','orgDraft','address','textarea',null,true)+field('City *','orgDraft','city')+field('State / union territory *','orgDraft','region')+field('PIN code *','orgDraft','pin')+field('Country','orgDraft','country','select',['India'])+field('Email','orgDraft','email','email')+field('Phone','orgDraft','phone','tel')+field('Website','orgDraft','website')+field('Address layout','orgDraft','addressFormat','select',[['stacked','Stacked lines'],['compact','Compact comma separated']])+uploadField('Company logo','logo')+'</div>';
 if(setupStep===1)h+='<div class="formgrid">'+field('GST registration','orgDraft','taxStatus','select',[['unregistered','Not GST registered'],['registered','GST registered']])+field('GSTIN (required if registered)','orgDraft','gstin')+field('PAN (optional)','orgDraft','pan')+field('Financial year','orgDraft','fy','select',['2026–27','2027–28'])+field('Base currency','orgDraft','currency','select',['INR'])+field('Invoice prefix *','orgDraft','prefix')+field('Next sequence number *','orgDraft','nextNo','number')+field('Default payment terms (days)','orgDraft','defaultDays','number')+'</div><p class="miniinfo">Number preview: <strong id="number-preview">'+esc(o.prefix+String(o.nextNo).padStart(3,'0'))+'</strong>. Production numbering must be allocated atomically by the server.</p>';
 if(setupStep===2)h+='<div class="formgrid">'+field('Bank name','orgDraft','bankName')+field('Account holder','orgDraft','accountName')+field('Account number','orgDraft','accountNo')+field('IFSC','orgDraft','ifsc')+field('Branch','orgDraft','branch')+field('UPI ID','orgDraft','upi')+uploadField('Payment QR code','qr')+'</div><div class="notice section">Upload your business payment QR. This prototype displays the image; it does not verify the payee or confirm payments.</div>';
 if(setupStep===3)h+='<div class="formgrid">'+field('Invoice style','orgDraft','template','select',[['classic','Classic teal'],['navy','Executive navy']])+field('Default thank-you note','orgDraft','note','textarea',null,true)+field('Default terms & conditions','orgDraft','terms','textarea',null,true)+uploadField('Authorized signature','signature')+'</div>'+[['showBank','Display bank details'],['showQr','Display payment QR'],['showSignature','Display authorized signature']].map(function(x){return '<label class="inlinecheck"><input type="checkbox" data-orgcheck="'+x[0]+'"'+(o[x[0]]?' checked':'')+'>'+x[1]+'</label>'}).join('');
 if(setupStep===4)h+='<div class="mini-list"><div><span>Legal name</span><b>'+esc(o.name)+'</b></div><div><span>GST</span><b>'+esc(o.taxStatus==='registered'?o.gstin:'Not registered')+'</b></div><div><span>Number series</span><b>'+esc(o.prefix+String(o.nextNo).padStart(3,'0'))+'</b></div><div><span>Bank / QR</span><b>'+(o.bankName?'Bank added':'No bank')+' · '+(o.qr?'QR added':'No QR')+'</b></div><div><span>Invoice notes</span><b>'+esc(o.note||'None')+'</b></div></div><div class="notice section">Saved only in this browser for review. Production sign-up, tenant access and secure storage are developer tasks.</div>';
 h+=errorBox()+'<div class="formactions">'+(setupStep?b('Back','setup-back','secondary'):'')+b(setupStep===4?'Save organization & finish':'Continue',setupStep===4?'setup-finish':'setup-next')+'</div></section><aside><div class="panel panelpad" style="margin-bottom:12px"><strong>Invoice preview</strong><p class="miniinfo">Preview updates as you type. Sample invoice; payment QR is optional.</p></div><div id="setup-preview">'+invoiceDocument({org:o,customer:state.customers[0]||{name:'Your customer',billing:'Customer billing address',shipping:'Customer delivery address'},invoice:previewInvoice(o)},'DRAFT PREVIEW')+'</div></aside></div>';return h}
function previewInvoice(o){var i=clone(state.invoice);i.number=o.prefix+String(o.nextNo).padStart(3,'0');i.notes=o.note;i.terms=o.terms;i.status='Draft';i.lines=i.lines.map(function(l){if(o.taxStatus!=='registered')l.tax=0;return l});i.freightTax=o.taxStatus==='registered'?18:0;return i}
calc=function(o){if(!Array.isArray(o.lines))return originalCalc(o);var c={base:0,tax:0,total:0,discount:0};o.lines.forEach(function(l){var gross=Number(l.qty)*Number(l.rate),d=Number(l.discount)||0,b=Math.max(0,gross-d);c.base+=b;c.discount+=d;c.tax+=Math.round(b*(Number(l.tax)||0))/100});var f=Number(o.freight)||0;c.base+=f;c.tax+=Math.round(f*(Number(o.freightTax)||0))/100;c.base=Math.round(c.base*100)/100;c.tax=Math.round(c.tax*100)/100;c.total=Math.round((c.base+c.tax+(Number(o.adjustment)||0))*100)/100;return c};
function taxBreakdown(i){var buckets={};i.lines.forEach(function(l){var rate=Number(l.tax)||0;var base=Math.max(0,Number(l.qty)*Number(l.rate)-Number(l.discount));buckets[rate]=(buckets[rate]||0)+Math.round(base*rate)/100});if(Number(i.freight)){var r=Number(i.freightTax)||0;buckets[r]=(buckets[r]||0)+Math.round(Number(i.freight)*r)/100}return Object.keys(buckets).map(function(r){var tax=Math.round(buckets[r]*100)/100;if(i.taxMode==='intra'){var cg=Math.round(tax/2*100)/100,sg=Math.round((tax-cg)*100)/100;return '<div class="totrow"><span>CGST '+(Number(r)/2)+'%</span><strong>'+fmt(cg)+'</strong></div><div class="totrow"><span>SGST '+(Number(r)/2)+'%</span><strong>'+fmt(sg)+'</strong></div>'}return '<div class="totrow"><span>IGST '+r+'%</span><strong>'+fmt(tax)+'</strong></div>'}).join('')}
function invoiceDocument(record,label){var o=record.org||emptyOrg,i=record.invoice,c=record.customer||{},t=calc(i),registered=o.taxStatus==='registered';return '<article class="invoice-card"'+(o.template==='navy'?' style="border-top-color:#0d2943"':'')+'><div class="doc-header"><div>'+(o.logo?'<img class="doc-logo" src="'+o.logo+'" alt="Company logo">':'')+'<h2>'+esc(o.name||'Your company name')+'</h2>'+(o.display&&o.display!==o.name?'<p>'+esc(o.display)+'</p>':'')+'<p>'+esc(orgAddress(o)||'Your business address')+'</p><p>'+esc([o.email,o.phone,o.website].filter(Boolean).join(' · '))+'</p>'+(registered?'<p><strong>GSTIN:</strong> '+esc(o.gstin||'Not entered')+'</p>':'<p>Not GST registered · no GST charged</p>')+'</div><div><span class="doc-copy">'+esc(label)+'</span><h2>'+(registered?'Tax invoice':'Invoice')+'</h2><p><strong>'+esc(i.number)+'</strong></p><p>Date: '+esc(i.date)+'\nDue: '+esc(i.due)+'</p><p>'+esc(i.status==='Draft'?'DRAFT · NOT ISSUED':'Issued copy · review prototype')+'</p></div></div><div class="doc-parties"><div><small class="muted">BILL TO</small><h3>'+esc((c.type==='business'&&c.company)||c.name||i.customer||'Select a customer')+'</h3><p>'+esc(c.billing||'')+'</p><p>'+esc(c.gstin?'GSTIN: '+c.gstin:'')+'</p><p>'+esc(c.email||'')+'</p></div><div><small class="muted">SHIP TO</small><h3>'+esc((c.type==='business'&&c.company)||c.name||i.customer||'Customer')+'</h3><p>'+esc(c.shipping||c.billing||'')+'</p><p><strong>Place of supply:</strong> '+esc(i.place||c.region||'')+'</p><p>'+esc(i.purchaseRef?'PO reference: '+i.purchaseRef:'')+'</p></div></div><table><thead><tr><th>Description / HSN-SAC</th><th>Qty / unit</th><th>Rate</th><th>Discount</th><th>GST</th><th>Taxable</th></tr></thead><tbody>'+i.lines.map(function(l){return '<tr><td><strong>'+esc(l.item)+'</strong><br>'+esc(l.hsn)+'</td><td>'+esc(l.qty)+' '+esc(l.unit)+'</td><td>'+fmt(l.rate)+'</td><td>'+fmt(l.discount)+'</td><td>'+esc(l.tax)+'%</td><td>'+fmt(Math.max(0,l.qty*l.rate-l.discount))+'</td></tr>'}).join('')+'</tbody></table><div class="totals"><div class="totrow"><span>Freight (before tax)</span><strong>'+fmt(i.freight)+'</strong></div><div class="totrow"><span>Taxable subtotal</span><strong>'+fmt(t.base)+'</strong></div>'+(registered?taxBreakdown(i):'')+'<div class="totrow"><span>Adjustment</span><strong>'+fmt(i.adjustment)+'</strong></div><div class="totrow grand"><span>Total · INR</span><span>'+fmt(t.total)+'</span></div></div>'+(i.kind==='goods'?'<div class="notice"><strong>Transport details</strong><p>'+esc(['Transporter: '+(i.transportName||'—'),'ID: '+(i.transporterId||'—'),'Mode / vehicle: '+i.transportMode+' / '+(i.vehicle||'—'),'LR / transport document: '+(i.lr||'—')+(i.lrDate?' · '+i.lrDate:''),'Dispatch: '+(i.dispatch||'—')+' → '+(i.destination||'—'),'Distance: '+(i.distance||'—')+' km',i.eway?'External e-way bill reference: '+i.eway+(i.ewayDate?' · '+i.ewayDate:''):'E-way bill not generated by this prototype'].join('\n'))+'</p></div>':'')+'<div class="bank-block"><div>'+(o.showBank&&o.bankName?'<h3>Bank details</h3><p>'+esc([o.accountName,o.bankName+(o.branch?' · '+o.branch:''),'Account: '+o.accountNo,'IFSC: '+o.ifsc].join('\n'))+'</p>':'')+(o.showQr&&o.upi?'<p>UPI: '+esc(o.upi)+'</p>':'')+'</div>'+(o.showQr&&o.qr?'<div><img class="doc-qr" src="'+o.qr+'" alt="Business payment QR"><p class="small-copy">Payment QR</p></div>':'')+'</div><div class="doc-note"><p>'+esc(i.notes||'')+'</p><p>'+esc(i.terms||'')+'</p>'+(o.showSignature&&o.signature?'<img class="signature" src="'+o.signature+'" alt="Authorized signature">':'')+'<p class="small-copy">Authorized signatory · '+esc(o.name)+'</p></div><p class="small-copy">YBS Books review prototype · No tax filing, IRN or payment confirmation is generated.</p></article>'}
function currentRecord(){return {org:clone(state.org||emptyOrg),customer:clone(state.customers.find(function(c){return c.id===state.invoice.customerId})||{}),invoice:clone(state.invoice)}}
function copyLabels(i){if(i.kind==='goods')return ['ORIGINAL FOR RECIPIENT','DUPLICATE FOR TRANSPORTER','TRIPLICATE FOR SUPPLIER'];return i.copies==='two'?['ORIGINAL FOR RECIPIENT','DUPLICATE FOR SUPPLIER']:['ORIGINAL FOR RECIPIENT','DUPLICATE FOR SUPPLIER','ADDITIONAL OFFICE COPY']}
function showCopies(record){var labels=copyLabels(record.invoice),dlg=document.getElementById('copies-dialog');dlg.innerHTML='<div class="dialogbar"><div><strong>'+esc(record.invoice.number)+' · '+labels.length+' copies</strong><p class="miniinfo">Same invoice number, values and issue snapshot on every copy.</p></div><div class="headbuttons">'+b('Print / Save PDF','print-copies')+b('Download invoice HTML','download-copies','secondary')+b('Close preview','close-copies','secondary')+'</div><p class="copies-note">For PDF output, use a desktop browser. If this in-app browser does not open printing, download the invoice HTML, open it in Chrome or Edge, and choose Print → Save as PDF.</p></div><div class="document-stack">'+labels.map(function(l){return invoiceDocument(record,l)}).join('')+'</div>';dlg.record=record;dlg.showModal();document.getElementById('print-area').innerHTML=labels.map(function(l){return invoiceDocument(record,l)}).join('')}
function newInvoice(){var o=state.org,number=o.prefix+String(o.nextNo).padStart(3,'0'),date=new Date(),due=new Date();due.setDate(due.getDate()+Number(o.defaultDays));var d=function(x){return x.getFullYear()+'-'+String(x.getMonth()+1).padStart(2,'0')+'-'+String(x.getDate()).padStart(2,'0')};state.invoice=clone(originalState.invoice);Object.assign(state.invoice,{number:number,date:d(date),due:d(due),notes:o.note,terms:o.terms,customerId:'',customer:'',gstin:'',place:o.region,lines:[{item:'',hsn:'',unit:'nos',qty:1,rate:0,discount:0,tax:o.taxStatus==='registered'?18:0}],freightTax:o.taxStatus==='registered'?18:0,status:'Draft'});state.receipt=0;persist();go('invoice')}
function lineInput(l,n,label,key,type){var id='line-'+n+'-'+key;return '<div class="field"><label for="'+id+'">'+label+'</label><input id="'+id+'" data-line="'+n+'" data-key="'+key+'" type="'+(type||'text')+'" value="'+esc(l[key])+'"'+(type==='number'?' min="0" step="0.01"':'')+'></div>'}
invoicePage=function(){var o=state.invoice,locked=o.status!=='Draft',record=locked?state.documents.find(function(d){return d.invoice.number===o.number}):null;if(locked&&record)return head('ISSUED INVOICE',o.number,'Issued details are locked. New organization settings apply to future invoices.',b('New invoice','new-invoice')+b('Invoice register','go-register','secondary'))+'<div class="notice">'+esc(o.status)+' · Total '+fmt(calc(o).total)+' · Received '+fmt(state.receipt)+' · Balance '+fmt(Math.max(0,calc(o).total-state.receipt))+'</div><div class="headbuttons" style="margin-bottom:20px">'+b('Preview all copies','preview-copies')+b('Record receipt','receipt-invoice','secondary')+'</div>'+invoiceDocument(record,copyLabels(record.invoice)[0]);
 return head('SALES WORKFLOW','Create invoice','Your organization, customer and payment details flow into every copy.',b('Invoice register','go-register','secondary')+b('Organization settings','go-organization','secondary'))+'<div class="notice">One transaction, multiple copies. Goods use recipient / transporter / supplier copies. Services default to your requested three-copy pack, with an additional office copy.</div><div class="split"><section class="panel panelpad"><div class="formgrid">'+field('Customer *','invoice','customerId','select',[['','Select customer']].concat(selectOptions(state.customers.filter(function(c){return c.role!=='vendor'}))))+field('Supply type','invoice','kind','select',[['services','Services'],['goods','Goods / transport']])+field('Invoice number (allocated on issue)','invoice','number')+field('Invoice date *','invoice','date','date')+field('Due date *','invoice','due','date')+field('Customer PO reference','invoice','purchaseRef')+field('Place of supply *','invoice','place')+field('Tax treatment (confirm manually)','invoice','taxMode','select',[['intra','Intra state · CGST + SGST'],['inter','Inter state · IGST']])+field('Service copy preference','invoice','copies','select',[['three','3 copies · includes office copy'],['two','2 copies · recipient & supplier']])+'</div>'+b('Add customer','new-customer','ghost small')+'<div class="fieldset"><h3>Items & services</h3><div class="field"><label for="catalogue-add">Add a catalogue item</label><select id="catalogue-add"><option value="">Choose item</option>'+state.catalogue.map(function(it){return '<option value="'+esc(it.id)+'">'+esc(it.name)+'</option>'}).join('')+'</select></div><div id="invoice-lines">'+o.lines.map(function(l,n){return '<div class="line-item"><div class="linegrid">'+lineInput(l,n,'Description *','item')+lineInput(l,n,'HSN / SAC','hsn')+lineInput(l,n,'Quantity *','qty','number')+lineInput(l,n,'Rate ₹','rate','number')+lineInput(l,n,'Discount ₹','discount','number')+lineInput(l,n,'GST %','tax','number')+'</div><div class="rowbetween" style="margin-top:10px">'+lineInput(l,n,'Unit','unit')+(o.lines.length>1?b('Remove line','remove-line-'+n,'secondary small'):'')+'</div></div>'}).join('')+'</div>'+b('+ Add line','add-line','ghost small')+'</div><div class="fieldset"><h3>Charges & invoice message</h3><div class="formgrid">'+field('Freight ₹ (before tax)','invoice','freight','number')+field('Freight GST %','invoice','freightTax','number')+field('Adjustment ₹ (+ / −)','invoice','adjustment','number')+field('Thank-you note','invoice','notes','textarea',null,true)+field('Terms & conditions','invoice','terms','textarea',null,true)+'</div></div><div id="transport-fields">'+(o.kind==='goods'?transportFields():'')+'</div><div class="fieldset"><h3>Totals</h3><div id="invoice-summary">'+invoiceTotals()+'</div></div>'+errorBox()+'<div class="formactions">'+b('Save draft','save-invoice','secondary')+b('Preview copies','preview-copies','ghost')+b('Issue & generate copies','issue-invoice')+'</div><p class="miniinfo">Drafts are auto-saved locally. Issue locks the snapshot; it does not file GST or create an e-way bill.</p></section><aside><div id="invoice-preview">'+invoiceDocument(currentRecord(),'DRAFT PREVIEW')+'</div></aside></div>'};
function invoiceTotals(){var c=calc(state.invoice);return '<div class="mini-list"><div><span>Subtotal incl. freight</span><b>'+fmt(c.base)+'</b></div><div><span>Total GST</span><b>'+fmt(c.tax)+'</b></div><div><span>Adjustment</span><b>'+fmt(state.invoice.adjustment)+'</b></div><div><span>Total invoice</span><b>'+fmt(c.total)+'</b></div></div>'}
function transportFields(){return '<div class="fieldset"><h3>Transport & dispatch</h3><p class="miniinfo">Optional review fields. Statutory applicability and validation belong in the production tax workflow.</p><div class="formgrid">'+field('Transporter name','invoice','transportName')+field('Transporter ID / GSTIN','invoice','transporterId')+field('Transport mode','invoice','transportMode','select',['Road','Rail','Air','Ship'])+field('Vehicle number','invoice','vehicle')+field('LR / transport document number','invoice','lr')+field('Transport document date','invoice','lrDate','date')+field('Dispatch from','invoice','dispatch')+field('Destination','invoice','destination')+field('Distance (km)','invoice','distance','number')+field('External e-way bill reference','invoice','eway')+field('External e-way bill date','invoice','ewayDate','date')+'</div><div class="notice gold section">A transporter invoice copy is not an e-way bill or delivery challan. No IRN or government QR is generated here.</div></div>'}
function blankCustomer(){return {id:'',role:'customer',type:'business',name:'',company:'',contact:'',email:'',phone:'',taxStatus:'unregistered',gstin:'',pan:'',region:'Andhra Pradesh',billing:'',shipping:'',sameAddress:true,terms:15,notes:''}}
function contactForm(){var c=state.customerDraft;if(!c||!Object.keys(c).length)return '';return '<section class="panel panelpad section"><h2>'+(c.id?'Edit contact':'New contact')+'</h2><div class="formgrid">'+field('Contact role','customerDraft','role','select',[['customer','Customer'],['vendor','Vendor'],['both','Customer & vendor']])+field('Customer type','customerDraft','type','select',[['business','Business / company'],['individual','Individual']])+field('Display / invoice name *','customerDraft','name')+(c.type==='business'?field('Company legal name *','customerDraft','company'):'')+field(c.type==='business'?'Primary contact person':'Full name (optional)','customerDraft','contact')+field('Email','customerDraft','email','email')+field('Phone','customerDraft','phone','tel')+field('GST treatment','customerDraft','taxStatus','select',[['unregistered','Unregistered / consumer'],['registered','GST registered']])+field('GSTIN (if registered)','customerDraft','gstin')+field('PAN (optional)','customerDraft','pan')+field('State / union territory *','customerDraft','region')+field('Payment terms (days)','customerDraft','terms','number')+field('Billing address *','customerDraft','billing','textarea',null,true)+'</div><label class="inlinecheck"><input id="sameAddress" type="checkbox"'+(c.sameAddress?' checked':'')+'>Shipping address is the same as billing</label>'+(c.sameAddress?'':'<div class="formgrid">'+field('Shipping address','customerDraft','shipping','textarea',null,true)+'</div>')+'<div class="formgrid">'+field('Internal notes','customerDraft','notes','textarea',null,true)+'</div>'+errorBox()+'<div class="formactions">'+b('Save contact','save-customer')+b('Cancel','cancel-customer','secondary')+'</div></section>'}
contactsPage=function(){return head('MASTER DATA','Customers & vendors','Individuals and businesses, with reusable billing and shipping details.',b('New customer / vendor','new-customer'))+'<div class="panel panelpad"><div class="field"><label for="contact-search">Search by name, email or GSTIN</label><input id="contact-search" type="search" placeholder="Find a contact"></div><div class="tablewrap"><table class="list"><thead><tr><th>Contact</th><th>Role / type</th><th>GST</th><th>Terms</th><th>Actions</th></tr></thead><tbody id="contact-rows">'+contactRows('')+'</tbody></table></div></div>'+contactForm()};
function contactRows(q){var cs=state.customers.filter(function(c){return [c.name,c.email,c.gstin].join(' ').toLowerCase().includes(q.toLowerCase())});return cs.map(function(c){return '<tr><td><strong>'+esc(c.name)+'</strong><br>'+esc(c.email)+'<br><span class="muted">'+esc(c.region)+'</span></td><td>'+esc(c.role)+' / '+esc(c.type)+'</td><td>'+esc(c.gstin||'Unregistered')+'</td><td>'+esc(c.terms)+' days</td><td><div class="contact-actions">'+b('Edit','edit-contact-'+c.id,'secondary small')+(c.role!=='vendor'?b('Invoice','invoice-contact-'+c.id,'ghost small'):'')+'</div></td></tr>'}).join('')||'<tr><td colspan="5" class="empty">No matching contacts. Add an individual or business to begin.</td></tr>'}
itemsPage=function(){var d=state.itemDraft;return head('MASTER DATA','Items & services','Reusable descriptions, unit prices, HSN / SAC and tax defaults.',b('New item / service','new-item'))+'<div class="panel panelpad tablewrap"><table class="list"><thead><tr><th>Description</th><th>Type</th><th>HSN / SAC</th><th>Unit</th><th>Rate</th><th>GST</th></tr></thead><tbody>'+state.catalogue.map(function(i){return '<tr><td>'+esc(i.name)+'</td><td>'+esc(i.kind)+'</td><td>'+esc(i.hsn)+'</td><td>'+esc(i.unit)+'</td><td>'+fmt(i.rate)+'</td><td>'+esc(i.tax)+'%</td></tr>'}).join('')+'</tbody></table><p class="miniinfo">Seed catalogue entries are examples; verify classifications and rates for the actual supply. Stock movements are not implemented.</p></div>'+(d&&Object.keys(d).length?'<section class="panel panelpad section"><h2>New item / service</h2><div class="formgrid">'+field('Name *','itemDraft','name')+field('Supply type','itemDraft','kind','select',[['services','Service'],['goods','Goods']])+field('HSN / SAC','itemDraft','hsn')+field('Unit','itemDraft','unit')+field('Rate ₹','itemDraft','rate','number')+field('GST rate %','itemDraft','tax','number')+'</div>'+errorBox()+'<div class="formactions">'+b('Save item','save-item')+b('Cancel','cancel-item','secondary')+'</div></section>':'')};
function registerPage(){return head('SALES','Invoice register','Issued snapshots remain unchanged when you edit your organization or contacts.',b('New invoice','new-invoice')+b('Current invoice','go-invoice','secondary'))+'<div class="notice gold">Payments and the inherited overview / reports demonstrate the current invoice and bill only. The register retains all issued invoice copies; consolidated ledgers are a production requirement.</div><section class="panel panelpad"><h2>Issued invoices · '+state.documents.length+'</h2><div class="history-list">'+(state.documents.map(function(d,n){return '<div class="history-item"><div><strong>'+esc(d.invoice.number)+'</strong><p class="miniinfo">'+esc(d.customer.name)+' · '+esc(d.invoice.date)+' · '+esc(d.invoice.kind)+' · '+copyLabels(d.invoice).length+' copies</p></div><div class="headbuttons"><strong>'+fmt(calc(d.invoice).total)+'</strong>'+b('View copies','history-'+n,'secondary small')+'</div></div>'}).join('')||'<div class="empty">Your first issued invoice will appear here.</div>')+'</div></section>'}
var gapRows=[['Organization onboarding','Illustrative profile only','Working 5-step setup; logo, address layout, tax, series, bank, QR, notes, signature','P0 · Server tenant profile, admin permissions, secured file storage'],['Customer / vendor masters','2 static contacts; create button was a placeholder','Create / edit individual or business; tax category, addresses, terms; invoice selection','P0 · Persistent tenant contacts, uniqueness and server validation'],['Invoice editor','One line; hard-coded brand; session-only draft','Multiple lines; item catalogue; freight, discount, taxes, notes; organization and customer details','P0 · Decimal arithmetic, tax policy, HSN / SAC / UQC and supply validation'],['Copy generation','Preview only; no printable copies','One issue event → 3 goods copies; 2 or 3 service copies; print / PDF via browser','P0 · Deterministic server PDF and approved templates'],['Transport','No transport fields','Transporter, vehicle, LR/date, dispatch/destination, distance and external e-way bill reference','P0 for goods · Applicability, challans, dispatch lifecycle, EWB / IRP integration'],['Issue history & numbering','Editable current transaction only','Locked issue snapshot, incrementing series, issue register; profile edits affect future copies','P0 · Atomic tenant / FY numbering, idempotency, immutable audit trail'],['Payments & reports','Single invoice / bill demo','Existing allocations retained for current document; prior copies archived','P0 · Balanced journals, multi-document allocations, credit notes, bank reconciliation, aging, financial reports'],['Security & operations','No real sign-in or database','Browser-local review data; export / clear controls','P0 · Authentication, tenant isolation, role enforcement, audit, backups / restore, monitoring'],['Sales / purchases','Single SO→invoice and PO→bill sample flows','Existing flows retained; new contacts available','P1 · Multi-order / partial conversion, approval, PO matching, purchase tax and attachments'],['Efficiency & growth','Not implemented','Documented in developer handoff','P1 / P2 · Estimates, recurring invoices, reminders, portal, import/export, inventory, expenses, bank feeds, multicurrency']];
function roadmapPage(){return head('DEVELOPER REVIEW','What changed. What comes next.','Focused comparison of the supplied YBS HTML with documented Zoho Books and TallyPrime workflows.',b('Download review data','export-data','secondary'))+'<a class="full-guide-link" href="./YBS-Books-Developer-Guide.html" target="_blank" rel="noopener">Open full developer guide ↗</a><div class="notice">This is a working review prototype. It is not production accounting software, a complete Zoho Books equivalent, or a tax-filing service.</div><div class="grid two">'+gapRows.map(function(r){return '<section class="panel panelpad roadmap-card '+(r[0]==='Security & operations'?'pending':'')+'"><p class="eyebrow">'+esc(r[0])+'</p><h2 style="font-size:16px">'+esc(r[2])+'</h2><p class="muted"><strong>Original:</strong> '+esc(r[1])+'</p><p><strong>Developer next:</strong> '+esc(r[3])+'</p></section>'}).join('')+'</div><section class="panel panelpad section"><h2>Research references · checked 26 October 2026</h2><p>Zoho separates organization defaults, reusable contacts and PDF templates. TallyPrime documents e-way bills as a separate workflow. YBS should adopt the workflow principles with its own interface.</p><ul><li><a target="_blank" rel="noopener" href="https://www.zoho.com/in/books/help/settings/organization/organization-profile.html">Zoho Books: organization profile</a></li><li><a target="_blank" rel="noopener" href="https://www.zoho.com/in/books/help/contacts/">Zoho Books: customers & vendors</a></li><li><a target="_blank" rel="noopener" href="https://www.zoho.com/in/books/help/settings/templates.html">Zoho Books: PDF templates</a></li><li><a target="_blank" rel="noopener" href="https://help.tallysolutions.com/tally-prime/e-way-bill-tallyprime/faq-e-way-bill-tally/">TallyPrime: e-way bill workflow</a></li><li><a target="_blank" rel="noopener" href="https://taxinformation.cbic.gov.in/content-page/explore-rules/1000139/1000001">CBIC: Rule 48 invoice copies and e-invoice exception</a></li></ul><p class="miniinfo">This is a focused feature review, not an exhaustive product or compliance audit. The developer handoff contains the production model, acceptance tests and launch checklist.</p></section>'}
dashboard=function(){return head('YBS BOOKS · REVIEW EDITION','A stronger start for your books','Set up your business, add your customers and generate branded invoice copies.',b(orgReady()?'New invoice':'Set up organization',orgReady()?'new-invoice':'go-organization')+b('Developer feature gaps','go-roadmap','secondary'))+'<div class="notice">Review prototype · Data stays in this browser. Use sample data for walkthroughs. '+(orgReady()?'Organization: <strong>'+esc(state.org.name)+'</strong>.':'Start with organization setup before issuing invoices.')+'</div><div class="grid three"><div class="panel stat"><div class="label">Organization</div><div class="number">'+(orgReady()?'Ready':'Set up')+'</div>'+b('Open settings','go-organization','ghost small')+'</div><div class="panel stat"><div class="label">Customers & vendors</div><div class="number">'+state.customers.length+'</div>'+b('Manage contacts','go-contacts','ghost small')+'</div><div class="panel stat"><div class="label">Issued invoices</div><div class="number">'+state.documents.length+'</div>'+b('Open register','go-register','ghost small')+'</div></div><section class="panel panelpad section"><h2>Your first invoice, in four steps</h2>'+[['1 · Business identity','Logo, legal name, address and GST details','organization'],['2 · Payment & appearance','Bank, payment QR, thank-you note and signature','organization'],['3 · Customers & items','Individual or business; reusable addresses and items','contacts'],['4 · Issue once, print copies','Recipient, transporter and supplier copies for goods','invoice']].map(function(a){return '<div class="progresscheck"><div><strong>'+a[0]+'</strong><p class="miniinfo">'+a[1]+'</p></div>'+b('Open','go-'+a[2],'secondary small')+'</div>'}).join('')+'</section><section class="panel panelpad section"><h2>Continue your accounting walkthrough</h2><p class="muted">The original sales orders, purchase orders, vendor bills, payments and illustrative reports are retained.</p><div class="headbuttons">'+b('Sales orders','go-sales-order','secondary')+b('Purchases','go-purchase-order','secondary')+b('Payments','go-payments','secondary')+b('Reports','go-reports','secondary')+'</div></section>'};
settingsPage=function(){return head('ADMIN','Review data & production access','Organization settings are now a separate, working setup flow.',b('Organization settings','go-organization'))+'<section class="panel panelpad"><h2>Browser review data</h2><p>Profile images, contacts, drafts, issued snapshots and activity are saved locally in this browser. This is not a server backup.</p><div class="headbuttons">'+b('Export review data (JSON)','export-data','secondary')+b('Clear all review data','reset-demo','danger')+'</div><p class="miniinfo">Export contains the details you entered, including bank data and images. No login, access-role enforcement or shared database is included.</p></section><section class="panel panelpad section"><h2>Production permissions to implement</h2><div class="mini-list"><div><span>Owner / admin</span><b>Manage organization, banks and users</b></div><div><span>Accountant</span><b>Create, approve, issue and allocate</b></div><div><span>Sales</span><b>Scoped drafts; no bank/profile edits</b></div><div><span>Auditor</span><b>Read-only records and audit access</b></div></div><div class="formactions">'+b('Full developer gap list','go-roadmap','secondary')+'</div></section>'};
routes.splice(1,0,{id:'organization',name:'Organization setup',icon:'◇',group:'WORKSPACE'});routes.splice(routes.findIndex(function(r){return r.id==='invoice'})+1,0,{id:'register',name:'Invoice register',icon:'▤',group:'SALES'});routes.push({id:'roadmap',name:'Developer review',icon:'✓',group:'ADMIN'});
render=function(){if(!orgReady()&&['dashboard','organization','roadmap','settings'].indexOf(state.route)<0)state.route='organization';if(state.route==='organization'||state.route==='register'||state.route==='roadmap'){nav();document.getElementById('main').innerHTML=state.route==='organization'?setupPage():state.route==='register'?registerPage():roadmapPage()}else originalRender();document.querySelector('.topright .badge').textContent=state.org?state.org.name:'Organization setup needed';document.querySelectorAll('[data-nav]').forEach(function(x){if(x.dataset.nav===state.route)x.setAttribute('aria-current','page')});if(state.route==='invoice'){var n=document.getElementById('invoice-number');if(n)n.disabled=true;var adj=document.getElementById('invoice-adjustment');if(adj)adj.removeAttribute('min');if(state.org&&state.org.taxStatus!=='registered'){document.querySelectorAll('[data-line][data-key=tax],#invoice-freightTax').forEach(function(x){x.disabled=true})}}persist()};
orderPage=function(model,sales){var partyKey=sales?'customer':'vendor',valid=state.customers.filter(function(c){return sales?c.role!=='vendor':c.role!=='customer'});if(!valid.some(function(c){return c.name===state[model][partyKey]}))state[model][partyKey]=valid.length?valid[0].name:'';var html=originalOrderPage(model,sales),div=document.createElement('div');div.innerHTML=html;var sel=div.querySelector('#'+model+'-'+(sales?'customer':'vendor')),cs=state.customers.filter(function(c){return sales?c.role!=='vendor':c.role!=='customer'});if(sel){sel.innerHTML='<option value="">Select '+(sales?'customer':'vendor')+'</option>'+cs.map(function(c){return '<option '+(state[model][sales?'customer':'vendor']===c.name?'selected':'')+'>'+esc(c.name)+'</option>'}).join('')}return div.innerHTML};
billPage=function(){var vs=state.customers.filter(function(c){return c.role!=='customer'});if(!vs.some(function(c){return c.name===state.bill.vendor}))state.bill.vendor=vs.length?vs[0].name:'';var div=document.createElement('div');div.innerHTML=originalBillPage();var sel=div.querySelector('#bill-vendor');if(sel)sel.innerHTML='<option value="">Select vendor</option>'+state.customers.filter(function(c){return c.role!=='customer'}).map(function(c){return '<option '+(state.bill.vendor===c.name?'selected':'')+'>'+esc(c.name)+'</option>'}).join('');return div.innerHTML};
updateTotals=function(){if(state.route==='invoice'){var p=document.getElementById('invoice-preview'),s=document.getElementById('invoice-summary');if(p&&state.invoice.status==='Draft')p.innerHTML=invoiceDocument(currentRecord(),'DRAFT PREVIEW');if(s)s.innerHTML=invoiceTotals()}else if(['bill','sales-order','purchase-order'].includes(state.route))originalUpdate()};
function syncCustomer(){var c=state.customers.find(function(x){return x.id===state.invoice.customerId});if(c){state.invoice.customer=c.name;state.invoice.gstin=c.gstin;state.invoice.place=c.region;state.invoice.taxMode=state.org.region.toLowerCase()===c.region.toLowerCase()?'intra':'inter';var due=new Date(state.invoice.date+'T12:00:00');due.setDate(due.getDate()+Number(c.terms));if(!isNaN(due))state.invoice.due=due.getFullYear()+'-'+String(due.getMonth()+1).padStart(2,'0')+'-'+String(due.getDate()).padStart(2,'0')}else{state.invoice.customer='';state.invoice.gstin=''}}
function invoiceValid(){var i=state.invoice;if(!orgReady())return fail('Finish organization setup first.');if(!state.customers.some(function(c){return c.id===i.customerId&&c.role!=='vendor'}))return fail('Select an existing customer.');if(!i.date||!i.due||i.due<i.date)return fail('Use a due date on or after the invoice date.');if(!i.place.trim())return fail('Enter the place of supply.');for(var l of i.lines){if(!l.item.trim()||!Number.isFinite(Number(l.qty))||Number(l.qty)<=0||!Number.isFinite(Number(l.rate))||Number(l.rate)<0||!Number.isFinite(Number(l.discount))||Number(l.discount)<0||Number(l.discount)>Number(l.qty)*Number(l.rate)||!Number.isFinite(Number(l.tax))||Number(l.tax)<0||Number(l.tax)>100)return fail('Every line needs a description, positive quantity, nonnegative rate, a discount within its value, and a GST rate from 0 to 100.');if(state.org.taxStatus==='registered'&&!l.hsn.trim())return fail('Enter an HSN / SAC for each GST invoice line.')}if(!Number.isFinite(Number(i.freight))||Number(i.freight)<0||!Number.isFinite(Number(i.freightTax))||Number(i.freightTax)<0||Number(i.freightTax)>100||!Number.isFinite(Number(i.adjustment))||calc(i).total<=0)return fail('Check freight, freight tax and adjustment. Invoice total must be positive.');if(state.org.taxStatus!=='registered'&&(i.lines.some(function(l){return Number(l.tax)!==0})||Number(i.freightTax)!==0))return fail('An unregistered organization cannot charge GST in this prototype.');if(!Number.isFinite(Number(i.distance))||Number(i.distance)<0)return fail('Distance cannot be negative.');return true}
function chooseCustomer(id){state.invoice.customerId=id;syncCustomer();persist();render()}
action=function(a){if(a==='setup-next'){if(assetPending)return fail('Wait for the selected image to finish loading.');if(!checkOrg(setupStep))return;setupStep=Math.min(4,setupStep+1);render();return}if(a==='setup-back'){setupStep=Math.max(0,setupStep-1);render();return}if(a==='setup-finish'){if(assetPending)return fail('Wait for the image to finish loading.');for(var k=0;k<4;k++)if(!checkOrg(k)){setupStep=k;render();return}state.org=clone(state.orgDraft);if(state.org.taxStatus!=='registered'&&state.invoice.status==='Draft'){state.invoice.lines.forEach(function(l){l.tax=0});state.invoice.freightTax=0}if(state.invoice.status==='Draft'&&!state.invoice.customerId)newInvoice();else go('dashboard');persist();message('Organization saved. New invoices use these defaults.');return}
 if(a==='sample-org'){state.orgDraft=Object.assign(clone(emptyOrg),{name:'Coastal Demo Enterprises',display:'Coastal Demo',address:'12 Sample Business Lane',city:'Visakhapatnam',pin:'530001',region:'Andhra Pradesh',note:'Thank you for choosing our business.',terms:'Payment due within the agreed terms. This is sample data.'});setupStep=0;state.customers=state.customers.length?state.customers:[Object.assign(blankCustomer(),{id:'demo-business',name:'Harbour Demo Studio',company:'Harbour Demo Studio',billing:'45 Example Road\nVisakhapatnam, Andhra Pradesh 530002',shipping:'45 Example Road\nVisakhapatnam, Andhra Pradesh 530002',sameAddress:true}),Object.assign(blankCustomer(),{id:'demo-individual',type:'individual',name:'Sample Individual',billing:'7 Sample Street\nHyderabad, Telangana 500001',shipping:'7 Sample Street\nHyderabad, Telangana 500001',region:'Telangana'}),Object.assign(blankCustomer(),{id:'demo-vendor',role:'vendor',name:'Pixel Demo Supplies',company:'Pixel Demo Supplies',billing:'10 Example Market\nVisakhapatnam 530001'})];render();message('Sample profile filled. Review each step and finish setup.');return}
 if(a.startsWith('remove-')&&['logo','qr','signature'].includes(a.slice(7))){state.orgDraft[a.slice(7)]='';render();return}
 if(a==='new-customer'){state.customerDraft=blankCustomer();activeCustomer=state.route==='invoice'?'invoice':null;go('contacts');setTimeout(function(){document.getElementById('customerDraft-name').focus()},0);return}
 if(a==='save-customer'){var c=state.customerDraft;if(!c.name.trim()||!c.billing.trim()||!c.region.trim()||(c.type==='business'&&!c.company.trim()))return fail('Enter the display name, billing address, state and company legal name for a business.');if(c.email&&!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(c.email))return fail('Enter a valid email address.');if(c.taxStatus==='registered'&&!/^\d{2}[A-Z]{5}\d{4}[A-Z][1-9A-Z]Z[0-9A-Z]$/.test(c.gstin))return fail('Enter a GSTIN in the expected format.');if(!Number.isInteger(Number(c.terms))||Number(c.terms)<0)return fail('Use zero or a positive whole number for payment terms.');if(!c.sameAddress&&!c.shipping.trim())return fail('Enter the separate shipping address, or use the billing address.');if(c.taxStatus!=='registered')c.gstin='';if(c.type==='individual')c.company='';if(c.sameAddress)c.shipping=c.billing;if(!c.id)c.id='c-'+Date.now().toString(36);var pos=state.customers.findIndex(function(x){return x.id===c.id});if(pos<0)state.customers.push(clone(c));else state.customers[pos]=clone(c);state.customerDraft={};activity('Contact saved',c.name);if(activeCustomer==='invoice'&&c.role!=='vendor'){activeCustomer=null;state.invoice.customerId=c.id;syncCustomer();go('invoice')}else render();persist();message('Contact saved. Issued invoices keep their original details.');return}
 if(a==='cancel-customer'){state.customerDraft={};if(activeCustomer==='invoice'){activeCustomer=null;go('invoice')}else render();return}
 if(a.startsWith('edit-contact-')){state.customerDraft=clone(state.customers.find(function(c){return c.id===a.slice(13)}));render();return}
 if(a.startsWith('invoice-contact-')){if(state.invoice.status!=='Draft')newInvoice();chooseCustomer(a.slice(16));go('invoice');return}
 if(a==='new-item'){state.itemDraft={name:'',kind:'services',hsn:'',unit:'service',rate:0,tax:18};go('items');return}
 if(a==='save-item'){var it=state.itemDraft;if(!it.name.trim()||!it.unit.trim()||!Number.isFinite(Number(it.rate))||Number(it.rate)<0||!Number.isFinite(Number(it.tax))||Number(it.tax)<0||Number(it.tax)>100)return fail('Enter an item name, unit, nonnegative rate and a tax rate from 0 to 100.');it.id='i-'+Date.now().toString(36);state.catalogue.push(clone(it));state.itemDraft={};render();message('Catalogue item saved.');return}
 if(a==='cancel-item'){state.itemDraft={};render();return}
 if(a==='add-line'){state.invoice.lines.push({item:'',hsn:'',unit:'nos',qty:1,rate:0,discount:0,tax:state.org.taxStatus==='registered'?18:0});render();return}
 if(a.startsWith('remove-line-')){if(state.invoice.lines.length>1)state.invoice.lines.splice(Number(a.slice(12)),1);render();return}
 if(a==='new-invoice'){if(!orgReady()){go('organization');return}if(state.invoice.status==='Draft'&&state.invoice.lines.some(function(l){return l.item||Number(l.rate)})){if(!confirm('Replace the current unissued draft? Issued invoices remain in the register.'))return}newInvoice();return}
 if(a==='save-invoice'){if(persist())message('Draft saved in this browser.');return}
 if(a==='preview-copies'){var rec=state.invoice.status==='Draft'?currentRecord():state.documents.find(function(d){return d.invoice.number===state.invoice.number});showCopies(rec);return}
 if(a.startsWith('history-')){showCopies(state.documents[Number(a.slice(8))]);return}
 if(a==='close-copies'){document.getElementById('copies-dialog').close();return}
 if(a==='print-copies'){document.getElementById('copies-dialog').close();setTimeout(function(){window.print()},100);return}
 if(a==='download-copies'){var dlg=document.getElementById('copies-dialog'),rec=dlg.record,css=document.querySelector('style[data-enhancements]').textContent;download(rec.invoice.number.replace(/[^a-z0-9_-]/gi,'_')+'-copies.html','<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'+esc(rec.invoice.number)+'</title><style>'+document.querySelector('style').textContent+css+'body{padding:24px}.print-area{display:block}.print-area .invoice-card{margin-bottom:24px}@media print{body{padding:0}}</style><body><main class="print-area">'+copyLabels(rec.invoice).map(function(l){return invoiceDocument(rec,l)}).join('')+'</main></body></html>','text/html;charset=utf-8');return}
 if(a==='issue-invoice'){if(state.invoice.status!=='Draft'){message('This invoice has already been issued.');return}if(!invoiceValid())return;var number=state.org.prefix+String(state.org.nextNo).padStart(3,'0');if(number.length>16)return fail('The invoice number is longer than 16 characters. Update the number series.');if(state.documents.some(function(d){return d.invoice.number===number}))return fail('This invoice number already exists. Update the next sequence in organization setup.');state.invoice.number=number;state.invoice.status='Issued';state.invoice.customer=state.customers.find(function(c){return c.id===state.invoice.customerId}).name;state.invoice.item=state.invoice.lines.map(function(l){return l.item}).join(', ');var rec=currentRecord();rec.issuedAt=new Date().toISOString();state.documents.push(rec);state.org.nextNo=Number(state.org.nextNo)+1;state.orgDraft.nextNo=state.org.nextNo;if(state.invoice.source)state.salesOrder.status='Invoiced';activity('Invoice issued',number+' · '+copyLabels(state.invoice).length+' copies from one snapshot');persist();render();showCopies(rec);return}
 if(a==='convert-salesOrder'){if(!orgReady())return;var so=state.salesOrder,c=state.customers.find(function(x){return x.name===so.customer&&x.role!=='vendor'});if(!c){message('Select a saved customer on the sales order first.');return}if(state.invoice.status==='Draft'&&state.invoice.lines.some(function(l){return l.item||Number(l.rate)})){if(!confirm('Replace the current invoice draft with this sales order?'))return}newInvoice();state.invoice.customerId=c.id;syncCustomer();state.invoice.lines=[{item:so.item,hsn:so.hsn,unit:'nos',qty:Number(so.qty),rate:Number(so.rate),discount:Number(so.discount),tax:state.org.taxStatus==='registered'?Number(so.tax):0}];state.invoice.source=so.number;state.invoice.purchaseRef=so.reference;state.salesOrder.status='Open';render();return}
 if(a==='reset-demo'){if(!confirm('Clear all locally saved YBS Books review data, including organization, contacts and invoice copies? Export first if needed.'))return;localStorage.removeItem(storageKey);location.hash='organization';location.reload();return}
 if(a==='export-data'){download('YBS-Books-Review-Data.json',JSON.stringify({version:1,exportedAt:new Date().toISOString(),data:state},null,2),'application/json');return}
 originalAction(a);persist();
};
document.addEventListener('click',function(e){var step=e.target.closest('[data-step]');if(step&&!step.disabled){setupStep=Number(step.dataset.step);render()}});
document.addEventListener('input',function(e){var x=e.target;if(x.dataset.line!==undefined&&state.invoice.status==='Draft'){state.invoice.lines[Number(x.dataset.line)][x.dataset.key]=x.type==='number'?Number(x.value):x.value;updateTotals()}if(x.dataset.model==='orgDraft'){if(['gstin','ifsc','pan'].includes(x.dataset.field)){state.orgDraft[x.dataset.field]=x.value.toUpperCase();x.value=state.orgDraft[x.dataset.field]}var p=document.getElementById('setup-preview');if(p)p.innerHTML=invoiceDocument({org:state.orgDraft,customer:state.customers[0]||{name:'Your customer',billing:'Customer billing address'},invoice:previewInvoice(state.orgDraft)},'DRAFT PREVIEW');var n=document.getElementById('number-preview');if(n)n.textContent=state.orgDraft.prefix+String(state.orgDraft.nextNo).padStart(3,'0')}if(x.id==='contact-search')document.getElementById('contact-rows').innerHTML=contactRows(x.value);if(x.dataset.model==='invoice')updateTotals();persist()});
document.addEventListener('change',async function(e){var x=e.target;if(x.dataset.asset){var file=x.files[0];if(!file)return;if(!['image/png','image/jpeg'].includes(file.type)||file.size>1024*1024){fail('Choose a PNG or JPEG image no larger than 1 MB.');x.value='';return}assetPending++;try{var uri=await new Promise(function(resolve,reject){var fr=new FileReader();fr.onload=function(){resolve(fr.result)};fr.onerror=reject;fr.readAsDataURL(file)});await new Promise(function(resolve,reject){var image=new Image();image.onload=resolve;image.onerror=reject;image.src=uri});state.orgDraft[x.dataset.asset]=uri;persist();render();message('Image added to the organization preview.')}catch(err){fail('That image could not be read. Choose another PNG or JPEG.')}finally{assetPending--}return}if(x.dataset.orgcheck){state.orgDraft[x.dataset.orgcheck]=x.checked;render();return}if(x.id==='sameAddress'){state.customerDraft.sameAddress=x.checked;render();return}if(x.dataset.model==='customerDraft'&&['type','taxStatus','role'].includes(x.dataset.field)){render();return}if(x.dataset.model==='invoice'&&x.dataset.field==='customerId'){syncCustomer();render();return}if(x.dataset.model==='invoice'&&x.dataset.field==='kind'){render();return}if(x.dataset.model==='orgDraft'&&['template','taxStatus'].includes(x.dataset.field)){render();return}if(x.id==='catalogue-add'&&x.value){var it=state.catalogue.find(function(i){return i.id===x.value}),line={item:it.name,hsn:it.hsn,unit:it.unit,qty:1,rate:Number(it.rate),discount:0,tax:state.org.taxStatus==='registered'?Number(it.tax):0};if(state.invoice.lines.length===1&&!state.invoice.lines[0].item&&!Number(state.invoice.lines[0].rate))state.invoice.lines=[line];else state.invoice.lines.push(line);if(it.kind==='goods')state.invoice.kind='goods';render();return}persist()});
document.querySelector('.shell').insertAdjacentHTML('afterbegin','<div class="prototype-strip">YBS Books · Interactive developer review · Browser-local sample workflow · No live accounting or filing</div>');
document.body.insertAdjacentHTML('beforeend','<dialog class="document-overlay" id="copies-dialog" aria-label="Invoice copies preview"></dialog><div class="print-area" id="print-area"></div>');
if(!orgReady())state.route='organization';

